def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    # Helper function: Given two indices i and j, returns the unique element between them
    def find_unique(i, j):
        while i < j:
            mid = (i + j) // 2
            if (arr[mid] - arr[i]) % 2 == 0:
                j = mid
            else:
                i = mid + 1
        return i

    left_index = find_unique(0, n-1)
    right_index = find_unique(left_index, n-1)

    # Ensure both indices are valid for accessing elements
    if right_index == n or right_index == n-1:
        right_index -= 1

    # Find the unique element
    while left_index <= right_index and arr[left_index] == arr[right_index]:
        left_index += 1

    return arr[left_index]

