def is_Sum_Of_Powers_Of_Two(n):
    while n > 0:
        if n & 1:  # Check if the least significant bit is set
            if n == 1:
                return True
            elif (n & (n - 1)) != 0:  # Check if n is a power of 2
                return False
            else:
                n >>= 1  # Right shift n to check the next bit
        else:
            n >>= 1  # Right shift n if the least significant bit is not set
    return False

