def max_sum(nums):
    def find_mis(nums):
        # Find the maximum increasing subsequence ending at each index
        mis = [1] * len(nums)
        for i in range(1, len(nums)):
            for j in range(i):
                if nums[i] > nums[j] and mis[i] < mis[j] + 1:
                    mis[i] = mis[j] + 1
        return mis

    def find_mds(nums):
        # Find the maximum decreasing subsequence starting at each index
        mds = [1] * len(nums)
        for i in range(len(nums) - 2, -1, -1):
            for j in range(len(nums) - 1, i, -1):
                if nums[i] > nums[j] and mds[i] < mds[j] + 1:
                    mds[i] = mds[j] + 1
        return mds

    # Calculate the MIS and MDS
    mis = find_mis(nums)
    mds = find_mds(nums)

    # Calculate the BIS
    bms = [mis[i] + mds[i] - 1 for i in range(len(mis))]
    return max(bms)

