def max_sub_array_sum_repeated(arr, k):
    def kadane_algorithm(A):
        max_current = max_global = A[0]
        for i in range(1, len(A)):
            max_current = max(A[i], max_current + A[i])
            if max_current > max_global:
                max_global = max_current
        return max_global

    n = len(arr)
    total_length = n * k

    # If k is infinite, we can just get the maximum sum of all elements in arr
    if k == float('inf'):
        return kadane_algorithm(arr)

    # Calculate prefix sums
    prefix_sums = [arr[0]]
    for num in arr[1:]:
        prefix_sums.append(prefix_sums[-1] + num)

    # Extend prefix sums to handle repeated array
    for _ in range(k-2):
        extended_prefix_sums = []
        extended_prefix_sums.append(prefix_sums[-1])
        for i in range(1, n):
            extended_prefix_sums.append(extended_prefix_sums[-1] + prefix_sums[i])
        prefix_sums = extended_prefix_sums

    # Compute the maximum sum with the repeated array
    max_sum = kadane_algorithm(prefix_sums)

    # Handle the case where the sum is negative or very large
    return max(max_sum, 0)

