def count_binary_seq(n):
    # Helper function: calculate binomial coefficient C(n, k)
    def binom(n, k):
        if k > n - k:  # Take advantage of symmetry
            k = n - k
        c = 1
        for i in range(k):
            c = c * (n - i) // (i + 1)
        return c

    # Initialize memoization table
    memo = {}

    def helper(length, sum_left):
        # Base case: if no more bits need to be added
        if length == 0:
            return int(sum_left == 0)

        # Check if result is already computed
        if (length, sum_left) in memo:
            return memo[(length, sum_left)]

        # Recurrence relation: count valid sequences for remaining length and sum_left
        count = helper(length - 1, sum_left + 1) + helper(length - 1, sum_left - 1)
        memo[(length, sum_left)] = count
        return count

    # Calculate the total number of valid sequences
    total_count = binom(2 * n, n)
    for s in range(-n, n + 1):
        total_count += helper(2 * n, s) * 2**abs(s)

    return total_count

